create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.WBS_ART_AKTION_REF (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH.',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Filiale-ID (6906, 3000, ...).',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Nebenbetrieb-ID (Lager, Filiale, ...).',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Artikelnummer.',
	AKTION_ID VARCHAR(10) NOT NULL COMMENT 'Aktionsnummer, Promotion-ID.',
	KJWO_VON NUMBER(38,0) NOT NULL COMMENT 'Start-Kalenderwoche der Aktion entsprechend dat_von.',
	DAT_VON DATE NOT NULL COMMENT 'Aktuelle Aktion gültig von: Datum im Format JJJJ-MM-TT.',
	DAT_BIS DATE NOT NULL COMMENT 'Aktuelle Aktion gültig bis: Datum im Format JJJJ-MM-TT.',
	AKTION_DAUER NUMBER(38,0) NOT NULL COMMENT 'Dauer der Aktion.',
	WTAG_ID_VON NUMBER(38,0) NOT NULL COMMENT 'Werbestart Wochentag.',
	MUTTER_WB_ID NUMBER(38,0) COMMENT 'Artikelnummer des Werbemutterartikels.',
	AKTION_ID_REF VARCHAR(10) NOT NULL DEFAULT '-1' COMMENT 'Aktionsnummer (historische Aktion), Promotion-ID.',
	DAT_VON_REF DATE NOT NULL DEFAULT CAST('01-01-1900' AS DATE) COMMENT 'Historische Aktion gültig von: Datum im Format JJJJ-MM-TT.',
	DAT_BIS_REF DATE COMMENT 'Historische Aktion gültig bis: Datum im Format JJJJ-MM-TT.',
	AKTION_REIHENFOLGE NUMBER(38,0) NOT NULL COMMENT 'Position in der Zeitlichen Reihenfolge der vergangenen Aktionen. Bei 0 gibt es keine vergleichbare historische Aktion.',
	ANZ_AKT_SELBE_DAUER NUMBER(38,0) COMMENT 'Anzahl Aktionen mit selber Dauer.',
	MENGE_SA_BME_REF NUMBER(38,3) COMMENT 'Tatsächlich verkaufte Promotion Menge in der historischen Aktion in BME (wurde gefiltert auf bewart = 1002, SonderAktion, beinhaltet auch BBY),',
	ZEITRAUM_KORRIGIERTE_MENGE_REF NUMBER(38,3) COMMENT 'Korrigierte Menge in BME (historische Referenzperiode).',
	ZEITRAUM_MENGE_AF_4WO_REF NUMBER(38,3) COMMENT 'Menge Abverkauf AF 4 Wochen vor Aktion (historische Referenzperiode).',
	SALES_FG_REF NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob in einer Woche Absätze vorhanden waren (historische Referenzperiode).',
	IN_GRUPPE_FG NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob ein Artikel zu einer Serie gehört.',
	ANZ_ART_IN_GRUPPE NUMBER(38,0) COMMENT 'Anzahl Artikel in Serie.',
	ANZ_ART_IN_GRUPPE_REF NUMBER(38,0) COMMENT 'Anzahl Artikel in Serie (historische Referenzperiode).',
	TV_FG_REF NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob der Artikel TV-Werbung hatte (historische Referenzperiode).',
	TITELSEITE_FG_REF NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob der Artikel Titelseiten-Werbung hatte (historische Referenzperiode).',
	RUECKSEITE_FG_REF NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob der Artikel Rückseiten-Werbung hatte (historische Referenzperiode).',
	GK_FG_REF NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob der Artikel eine Gondelkopfplatzierung hatte (historische Referenzperiode).',
	VK_AKTION_BRUTTO_REF NUMBER(38,2) COMMENT 'VK-Preis Aktion Brutto (historische Referenzperiode).',
	VK_VOR_AKTION_BRUTTO_REF NUMBER(38,2) COMMENT 'VK-Preis vor Aktion Brutto (historische Referenzperiode).',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Währung, z.B. CZK, EUR.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	MULTI_OFFER_ID_FG_REF NUMBER(38,0) COMMENT 'Flag zur Markierung von Aktionszeiträumen mit multiplen Angeboten. Im selben Zeitraum können für einen Artikel mehrere Angebote existieren, z.B. über den Prospekt und über die K-Card.',
	BONUSKAUF_FG_REF NUMBER(38,0) COMMENT 'Flag zur Markierung von Bonusbuy-Aktionen. Zuordnung von BONUSKAUF_ID und AKTION_ID steht in L_BONUSKAUF.',
	LOKALE_GESCHAEFTSVORFALL_BEZ_REF VARCHAR(40) COMMENT 'Bezeichnung des Bonusbuy-Geschäftsvorfalls in lokaler Sprache. Zuordnung von BONUSKAUF_ID und GESCHAEFTSVORFALL_ID steht in L_BONUSKAUF.',
	MANDANT_ID_VZ NUMBER(38,0) COMMENT 'Mandant VZ. Das Auslieferungsland kann sich in gewissen Fällen vom Markt unterscheiden, z.B. wird Moldau (mandant_id 4) aus Rumänien (mandant_id 7) beliefert. Das Attribut wird hier redundant angelegt um die Performance im Frontend zu steigern (es wird ein Join mit WBS_WERBEAENDERUNGEN vermieden).',
	WUP_ID_VZ NUMBER(38,0) COMMENT 'WUP ID VZ. Marktnummer des Verteilzentrums. Das Attribut wird hier redundant angelegt um die Performance im Frontend zu steigern.',
	WUP_ID_REF NUMBER(38,0) COMMENT 'Der Referenzmarkt, der fuer den Aktionsvergleich gespeichert wird. Fuer eine zukuenftige Aktion eines Artikels in einem Markt werden Liefer- und Abverkaufsdaten einer vergangenen Aktion und dem Referenzartikel und -markt herangezogen. Muss nicht gleich sein zu Artikel und Markt der geplanten Aktion sein. Der Referenztyp sagt aus um welche Art von Vergleich es sich handelt.\n            Fuer WBS_ART_WUP_REF_TYP_ID = [2,3,4] kommt es aus der Tabelle ART_WUP_STATUS_REFERENZ, welche manuell von Nutzern gepflegt.\n            Fuer den Fall, dass WBS_ART_WUP_REF_TYP_ID = 1 werden die Werte aus Tabelle WBS_ART_AKTION_PER eingefuegt: ART_ID_REF = ART_ID, WUP_ID_REF = WUP_ID und NB_ID_REF = NB_ID sowie FAKTOR_REF = 1.',
	NB_ID_REF NUMBER(38,0) COMMENT 'NB_ID_REF, welche zur WUP_ID_REF gehört.',
	ART_ID_REF NUMBER(38,0) COMMENT 'Der Referenzartikel, der für den Artikelvergleich gespeichert wurde. Fuer eine zukuenftige Aktion eines Artikels in einem Markt werden Liefer- und Abverkaufsdaten einer vergangenen Aktion und dem Referenzartikel und -markt herangezogen. Muss nicht gleich sein zu Artikel und Markt der geplanten Aktion sein. Der Referenztyp sagt aus um welche Art von Vergleich es sich handelt.\n            Fuer WBS_ART_WUP_REF_TYP_ID = [2,3,4] kommt es aus der Tabelle ART_WUP_STATUS_REFERENZ, welche manuell von Nutzern gepflegt.\n            Fuer den Fall, dass WBS_ART_WUP_REF_TYP_ID = 1 werden die Werte aus Tabelle WBS_ART_AKTION_PER eingefuegt: ART_ID_REF = ART_ID, WUP_ID_REF = WUP_ID und NB_ID_REF = NB_ID sowie FAKTOR_REF = 1.',
	FAKTOR_REF NUMBER(38,2) COMMENT 'Faktor für die Gewichtung der Referenzmetriken.\n            Fuer WBS_ART_WUP_REF_TYP_ID = [2,3,4] kommt es aus der Tabelle ART_WUP_STATUS_REFERENZ, welche manuell von Nutzern gepflegt.\n            Fuer den Fall, dass WBS_ART_WUP_REF_TYP_ID = 1 werden die Werte aus Tabelle WBS_ART_AKTION_PER eingefuegt: ART_ID_REF = ART_ID, WUP_ID_REF = WUP_ID und NB_ID_REF = NB_ID sowie FAKTOR_REF = 1.',
	WBS_ART_WUP_REF_TYP_ID NUMBER(38,0) COMMENT 'Artikel_WUP (MARKT) Referenztyp id ,(zeigt die Art des vergleich an bezüglich   Art_ID mit  ART_ID_REF und  WUP_ID mit WUP_ID_REF)\n            \""1\tgleicher Artikel, gleicher Markt\n            2\tanderer Artikel, gleicher Markt\n            3\tgleicher Artikel, anderer Markt\n            4\tanderer Artikel, anderer Markt\""',
	BERECHNETE_MENGE_GESAMT_BME_REF NUMBER(38,3) COMMENT 'Gibt die urspruenglich berechnete Werbemenge fuer diese Artikel-Markt-Aktion-Kombination aus.',
	LIEF_MENGE_INITIAL_BME_REF NUMBER(38,3) COMMENT 'Liefermenge, die für die Erstlieferung versendet wurde, in BME. Gibt die tatsaechlich gelieferte Menge in der initialen Belieferung an (nach Fair Share).',
	LIEF_MENGE_HOCHRECHNUNG_BME_REF NUMBER(38,3) COMMENT 'Liefermenge, die nach der Anpassungsberechnung versendet wurde, in BME. Gibt die tatsaechlich gelieferte Menge aus der Hochrechnung an (nach Fair Share). WBS führt eine Berechnung nach der Initialen Belieferung durch (Hochrechnung), was dann die nachgelieferte Menge in der betrachteten Spalte beinflusst (kann auch 0 sein). Die Summe von lief_menge_initial_bme_ref und lief_menge_hochrechnung_bme_ref kann sich unterscheiden von berechnete_menge_gesamt_bme_ref.',
	LIEF_MENGE_ANTEIL_PROZENT_REF NUMBER(38,2) COMMENT 'Gibt an, wieviel % der Werbeware im Vergleich zur urspruenglich berechneten Werbemenge ausgeliefert wurde. Dies dient dem User dazu zu bewerten, ob der Werbeabsatz eventuell zu gering war, weil Ware nicht im Markt vorhanden war.\n            \""(MENGE_INITIAL_BME + MENGE_WBS [nach Umrechnung von AME zu BME]) / MENGE_GESAMT_BME\""',
	NUR_ONLINE_FG_REF NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob die Werbung nur online geschaltet wurde.',
	KUNDENKARTE_PERSONALISIERT_FG_REF NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob die Werbung ein personalisierter Kundenkarten-Coupon ist.',
	STILLE_AKTION_FG_REF NUMBER(38,0) COMMENT 'Flag: Stille Aktion Typ: \""In Store Promotions\"" (ohne Mengenberechnung) - Identifikation, um Artikel mit dieser FG aus der Berechnung auszuschließen.\n            Stille Aktionen sind Werbungen, die nur in Geschäften zu sehen sind und nirgendwo beworben wurden, und können je nach Typ eine Mengenberechnung haben oder nicht. Der Typ wird im Voraus von einem User vergeben. Für diesen Typ Stille Aktion werden keine Mengenberechnungen durchgeführt.',
	STILLE_AKTION_MIT_MENGE_FG_REF NUMBER(38,0) COMMENT 'Flag: Stille Aktion Typ: \""In Store Promotions mit Menge\"" - für Kombination WERBEMITTEL_ART_ID = 0920 & WERBEMITTEL_ID = 50. Artikel wird nur in Filiale beworben, erhält aber Mengenberechnung.\n            Stille Aktionen sind Werbungen, die nur in Geschäften zu sehen sind und nirgendwo beworben wurden, und können je nach Typ eine Mengenberechnung haben oder nicht. Der Typ wird im Voraus von einem User vergeben. Für diesen Typ Stille Aktion werden Mengenberechnungen durchgeführt.',
	WERBEFLAECHE_ABSCHNITT_NAME_REF VARCHAR(100) COMMENT 'Gibt an, in welchem Abschnitt eines Bereichs (in einer Werbeflyerseite) das Angebot abgebildet ist (z.B. TOPLEFT1) - Section (of leaflet page) where the advertisement is put.',
	WERBEFLAECHE_THEMA_BEZ_REF VARCHAR(100) COMMENT 'Bezeichnung für die WERBEFLAECHE_THEMA_ID (z.B. PANO01 = Schulanfang) - Name of the promotion theme.',
	MENGE_GESAMT_BME_REF NUMBER(38,3) COMMENT 'Die Summe der gesamten Promotionsmenge, die während des Aktionszeitraums verkauft wurde, unabhängig davon, ob sie durch die Promotion oder aus anderen Gründen, z.B. Kundenkartenrabatt verkauft wurde, in BME (für bewart = Sonderaktion und aktionsfrei, z.B. Kundenkarte, Bonusrabatt, etc.).',
	FIXMENGE_FG_REF NUMBER(38,0) COMMENT 'Fixmenge EK Flag gibt an, ob vom Einkauf eine Fixmenge für diese Aktion festgelegt wurde. Aus dbp_data.wbs_werbeaenderungen.',
	FIXMENGE_WFL_FG_REF NUMBER(38,0) COMMENT 'Fixmenge WFL Flag gibt an, ob vom Warenfluss eine Fixmenge für diese Aktion festgelegt wurde. Aus dbp_data.wbs_werbeaenderungen.',
	MINDESTPLATZIERUNG_FG_REF NUMBER(38,0) COMMENT 'Flag gibt an, ob vom Warenfluss eine Mindestplatzierung für diese Aktion festgelegt wurde. Aus dbp_data.wbs_werbeaenderungen.',
	constraint PK_WBS_ART_AKTION_REF primary key (MANDANT_ID, WUP_ID, NB_ID, ART_ID, AKTION_ID, DAT_VON, AKTION_ID_REF, DAT_VON_REF, AKTION_REIHENFOLGE)
)COMMENT='SCM-WBS - Operational data for WBS tool. This table is used in WBS frontend. It contains information about the historical article promotions in reference to new promotions. For a new promotion of an article it shows the identical previous promotions.'
;
